fn main(pre_initialized: pub bool, pre_s0: pub u64, arg_p0: pub u64, post_s0: pub u64, post_initialized: pub bool, result: pub u64) {
    assert(pre_initialized == true);
    let t0: u64 = arg_p0 + 4;
    let t1: bool = arg_p0 < t0;
    if t1 {
      let t2: u64 = pre_s0 + 1;
      let t3: u64 = arg_p0 + 1;
      let t4: u64 = arg_p0 + 4;
      let t5: bool = t3 < t4;
      if t5 {
        let t6: u64 = t2 + 1;
        let t7: u64 = t3 + 1;
        let t8: u64 = arg_p0 + 4;
        let t9: bool = t7 < t8;
        if t9 {
          let t10: u64 = t6 + 1;
          let t11: u64 = t7 + 1;
          let t12: u64 = arg_p0 + 4;
          let t13: bool = t11 < t12;
          if t13 {
            let t14: u64 = t10 + 1;
            let t15: u64 = t11 + 1;
            let t16: u64 = arg_p0 + 4;
            let t17: bool = t15 < t16;
            if t17 {
              let t18: u64 = t14 + 1;
              let t19: u64 = t15 + 1;
              let t20: u64 = arg_p0 + 4;
              let t21: bool = t19 < t20;
              if t21 {
                let t22: u64 = t18 + 1;
                let t23: u64 = t19 + 1;
                let t24: u64 = arg_p0 + 4;
                let t25: bool = t23 < t24;
                if t25 {
                  let t26: u64 = t22 + 1;
                  let t27: u64 = t23 + 1;
                  let t28: u64 = arg_p0 + 4;
                  let t29: bool = t27 < t28;
                  if t29 {
                    let t30: u64 = t26 + 1;
                    let t31: u64 = t27 + 1;
                    let t32: u64 = arg_p0 + 4;
                    let t33: bool = t31 < t32;
                    if t33 {
                      let t34: u64 = t30 + 1;
                      assert(t34 == t34);
                      assert(false);
                    } else {
                      assert(post_s0 == t30);
                      assert(post_initialized == true);
                      assert(result == t30);
                    }
                  } else {
                    assert(post_s0 == t26);
                    assert(post_initialized == true);
                    assert(result == t26);
                  }
                } else {
                  assert(post_s0 == t22);
                  assert(post_initialized == true);
                  assert(result == t22);
                }
              } else {
                assert(post_s0 == t18);
                assert(post_initialized == true);
                assert(result == t18);
              }
            } else {
              assert(post_s0 == t14);
              assert(post_initialized == true);
              assert(result == t14);
            }
          } else {
            assert(post_s0 == t10);
            assert(post_initialized == true);
            assert(result == t10);
          }
        } else {
          assert(post_s0 == t6);
          assert(post_initialized == true);
          assert(result == t6);
        }
      } else {
        assert(post_s0 == t2);
        assert(post_initialized == true);
        assert(result == t2);
      }
    } else {
      assert(post_s0 == pre_s0);
      assert(post_initialized == true);
      assert(result == pre_s0);
    }
}
